-- 纵向项目申报计划：发布窗口、类别和说明可配置。
BEGIN;

CREATE TABLE IF NOT EXISTS "纵向项目申报计划" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "计划年度" integer NOT NULL,
    "申报类别" integer NOT NULL DEFAULT 1,
    "计划名称" varchar(200) NOT NULL,
    "发布开始日期" date NOT NULL,
    "截止日期" date NOT NULL,
    "计划说明" varchar(2000),
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "创建人编号" integer,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_纵向项目申报计划" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_纵向项目申报计划_年度" CHECK ("计划年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_纵向项目申报计划_类别" CHECK ("申报类别" BETWEEN 1 AND 3),
    CONSTRAINT "ck_纵向项目申报计划_日期" CHECK ("截止日期" >= "发布开始日期"),
    CONSTRAINT "ck_纵向项目申报计划_状态" CHECK ("状态" IN ('草稿','发布','关闭')),
    CONSTRAINT "uq_纵向项目申报计划_名称" UNIQUE ("计划年度", "申报类别", "计划名称")
);

CREATE INDEX IF NOT EXISTS "ix_纵向项目申报计划_状态日期"
    ON "纵向项目申报计划" ("状态", "发布开始日期", "截止日期");

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (203, 2, '申报计划', '科研办公/科研办公/纵向项目申报计划.html', TRUE, '发布和维护纵向项目申报计划')
ON CONFLICT ("编号") DO UPDATE
SET "上级编号"=EXCLUDED."上级编号", "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "类型"=EXCLUDED."类型", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 203 FROM "角色" r
 WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
   AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=203);

UPDATE "系统迁移版本"
   SET "版本"=64, "脚本"='001-064', "检查摘要"='增加纵向项目申报计划发布、查询和菜单入口'
 WHERE "编号"=1;

COMMIT;
